"""Embed the editable Wi-Fi page into the ESP32 HTTP server; run before build."""
from pathlib import Path
root = Path(__file__).resolve().parents[1]
html = (root / 'phone/wifi.html').read_text(encoding='utf-8')
assert ')CARPAGE"' not in html
(root / 'main/web_server/remote_page.h').write_text(
    '// Generated by tools/embed_wifi_page.py from phone/wifi.html\n'
    '#pragma once\nstatic const char kRemotePage[]=R"CARPAGE(' + html + ')CARPAGE";\n', encoding='utf-8')
